-- ============================================================
-- VANIK MERCHANT TRANSACTIONS DATABASE SCHEMA & DATA SET
-- ============================================================

CREATE TABLE IF NOT EXISTS merchant_transactions (
    id SERIAL PRIMARY KEY,
    txn_date DATE NOT NULL,
    category VARCHAR(50) NOT NULL,
    transaction_id VARCHAR(100) NOT NULL,
    settlement_date DATE,
    debit NUMERIC(12, 2) DEFAULT 0.00,
    credit NUMERIC(12, 2) DEFAULT 0.00,
    balance NUMERIC(12, 2) DEFAULT 0.00,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);



-- ANALYTICAL KPI QUERIES FOR DASHBOARD CALCULATIONS

-- 1. Total Credit Revenue (Total Inflow)
SELECT SUM(credit) AS total_revenue_credit FROM merchant_transactions;

-- 2. Total Outflow (Debits & Expenses)
SELECT SUM(debit) AS total_debit_outflow FROM merchant_transactions;

-- 3. Net Cashflow (Credit - Debit)
SELECT (SUM(credit) - SUM(debit)) AS net_cashflow FROM merchant_transactions;

-- 4. Category Wise Breakdown
SELECT category, COUNT(*) AS txn_count, SUM(credit) AS total_credit, SUM(debit) AS total_debit 
FROM merchant_transactions 
GROUP BY category 
ORDER BY total_credit DESC, total_debit DESC;

-- 5. Monthly Revenue & Debit Trends
SELECT TO_CHAR(txn_date, 'YYYY-MM') AS month, SUM(credit) AS monthly_credit, SUM(debit) AS monthly_debit, COUNT(*) AS total_txns
FROM merchant_transactions
GROUP BY TO_CHAR(txn_date, 'YYYY-MM')
ORDER BY month ASC;
